import{_ as e,o,c as i,a2 as r}from"./chunks/framework.Do1fvF3d.js";const m=JSON.parse('{"title":"Términos y condiciones","description":"","frontmatter":{},"headers":[],"relativePath":"legal/terminos.md","filePath":"legal/terminos.md","lastUpdated":1791064393000}'),s={name:"legal/terminos.md"};function n(t,a,l,d,c,p){return o(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="terminos-y-condiciones" tabindex="-1">Términos y condiciones <a class="header-anchor" href="#terminos-y-condiciones" aria-label="Permalink to &quot;Términos y condiciones&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Borrador</p><p>Este documento es un borrador pendiente de revisión legal.</p></div><p><strong>Versión:</strong> 2026-10-03</p><h2 id="_1-el-servicio" tabindex="-1">1. El servicio <a class="header-anchor" href="#_1-el-servicio" aria-label="Permalink to &quot;1. El servicio&quot;">​</a></h2><p>Tranqui identifica llamadas y ayuda a bloquear spam usando información aportada por la comunidad. Es gratuito y de código abierto (AGPL-3.0).</p><h2 id="_2-requisitos" tabindex="-1">2. Requisitos <a class="header-anchor" href="#_2-requisitos" aria-label="Permalink to &quot;2. Requisitos&quot;">​</a></h2><p>Debes ser mayor de 18 años, o contar con la autorización de tus representantes legales.</p><h2 id="_3-uso-aceptable" tabindex="-1">3. Uso aceptable <a class="header-anchor" href="#_3-uso-aceptable" aria-label="Permalink to &quot;3. Uso aceptable&quot;">​</a></h2><p>No puedes:</p><ul><li>reportar números como spam a sabiendas de que no lo son, ni coordinar reportes falsos;</li><li>usar Tranqui para acosar o identificar a personas;</li><li>intentar extraer datos de forma masiva o automatizada;</li><li>usar etiquetas ofensivas o que contengan datos personales de otros.</li></ul><p>Podemos limitar o cerrar cuentas que incumplan estas reglas.</p><h2 id="_4-informacion-de-la-comunidad" tabindex="-1">4. Información de la comunidad <a class="header-anchor" href="#_4-informacion-de-la-comunidad" aria-label="Permalink to &quot;4. Información de la comunidad&quot;">​</a></h2><p>Los nombres y el marcado como spam provienen de lo que aportan otros usuarios. Hacemos lo posible para que sean correctos, pero pueden equivocarse. Si tu número aparece mal, <a href="/Tranqui/guia/apelacion">pide una revisión</a>.</p><h2 id="_5-disponibilidad" tabindex="-1">5. Disponibilidad <a class="header-anchor" href="#_5-disponibilidad" aria-label="Permalink to &quot;5. Disponibilidad&quot;">​</a></h2><p>El servicio se ofrece &quot;tal como está&quot;. Si no hay conexión o el servicio no responde, las llamadas suenan normalmente.</p><h2 id="_6-privacidad" tabindex="-1">6. Privacidad <a class="header-anchor" href="#_6-privacidad" aria-label="Permalink to &quot;6. Privacidad&quot;">​</a></h2><p>El tratamiento de datos se rige por la <a href="/Tranqui/legal/politica-de-tratamiento">Política de tratamiento de datos</a>.</p><h2 id="_7-contacto" tabindex="-1">7. Contacto <a class="header-anchor" href="#_7-contacto" aria-label="Permalink to &quot;7. Contacto&quot;">​</a></h2><p><span class="placeholder">[CORREO DE CONTACTO]</span></p>',19)])])}const h=e(s,[["render",n]]);export{m as __pageData,h as default};
